/***************************************************************************//*                                                                         *//* isupper() and friends : Unix library (OS9/68000)                        *//* =====================                                                   *//*                                                                         *//* Compiler:   Microware C                                                 *//* OS:         OS9/68000                                                   *//*                                                                         *//* Edition History                                                         *//* ===============                                                         *//*                                                                         *//* Ed. 0.00  Date 08/22/2026                                               *//*           First version, written for the OS-9 freeware collection.      *//*           SRC/nobs would not link: it calls isupper() as a FUNCTION,     *//*           and this system has it only as a macro.                       *//*                                                                         *//***************************************************************************//*                                                                         *//* Description                                                             *//*                                                                         *//*     SYNOPSIS          int isupper (c), islower (c), isalpha (c), isdigit (c),              isalnum (c), isspace (c), ispunct (c), isprint (c),              iscntrl (c), isxdigit (c), toupper (c), tolower (c);          int c;     DESCRIPTION          <ctype.h> defines all of these as MACROS over the _chcodes          table, which is the fast path and is what nearly every program          gets.  A program that takes their address, or that calls one          without including <ctype.h>, needs a real function -- ANSI          requires both to exist -- and this system supplied only the          macro.          These are deliberately written WITHOUT including <ctype.h>, so          the macros cannot capture the definitions.  They test the same          _chcodes table the macros do, so a program cannot get one          answer from the macro and a different one from the function.*/extern char _chcodes[];      /* in chcodes.r, the table the macros use */#define _CONTROL 0x01#define _UPPER   0x02#define _LOWER   0x04#define _DIGIT   0x08#define _WHITE   0x10#define _PUNCT   0x20#define _HEXDIG  0x40int isascii (c) int c; { return ((unsigned) c <= 0x7f); }int isupper (c) int c; { return (_chcodes[c] & _UPPER); }int islower (c) int c; { return (_chcodes[c] & _LOWER); }int isalpha (c) int c; { return (_chcodes[c] & (_UPPER | _LOWER)); }int isdigit (c) int c; { return (_chcodes[c] & _DIGIT); }int isxdigit(c) int c; { return (_chcodes[c] & _HEXDIG); }int isspace (c) int c; { return (_chcodes[c] & _WHITE); }int ispunct (c) int c; { return (_chcodes[c] & _PUNCT); }int iscntrl (c) int c; { return (_chcodes[c] & _CONTROL); }int isalnum (c) int c; { return (_chcodes[c] & (_UPPER | _LOWER | _DIGIT)); }int isprint (c) int c;     { return (_chcodes[c] & (_PUNCT | _UPPER | _LOWER | _DIGIT)); }int toupper (c) int c; { return ((_chcodes[c] & _LOWER) ? (c & 0xdf) : c); }int tolower (c) int c; { return ((_chcodes[c] & _UPPER) ? (c | 0x20) : c); }